using EnergyBillingEngine.Domain;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace EnergyBillingEngine.Infrastructure.Persistence.Configurations;

internal sealed class CustomerConfiguration : IEntityTypeConfiguration<Customer>
{
    public void Configure(EntityTypeBuilder<Customer> builder)
    {
        builder.ToTable("Customers");

        // Guid keys are generated by EF when an entity is added. On SQL Server EF uses sequential GUIDs,
        // which keep inserts at the end of the clustered index; a UUIDv7 would not, because SQL Server
        // orders uniqueidentifier values by their last six bytes first.
        builder.HasKey(c => c.Id);

        builder.Property(c => c.CustomerNumber).HasMaxLength(Customer.CustomerNumberMaxLength).IsUnicode(false);
        builder.HasIndex(c => c.CustomerNumber).IsUnique();

        builder.Property(c => c.Name).HasMaxLength(Customer.NameMaxLength);

        // Contracts and invoices are records that must survive; deleting a customer with contracts is refused.
        builder.HasMany(c => c.Contracts)
            .WithOne()
            .HasForeignKey(c => c.CustomerId)
            .OnDelete(DeleteBehavior.Restrict);
    }
}
